    LANGUAGE_WRAPPER = 'Generalized problem family (harder variant of AIME-style extremal setup):\n\nLet {a} be a prime greater than {lower_bound} with {a} \\equiv {residue} \\pmod{{q}}. For complex numbers z_n (1 \\le n \\le {a}), both the real and imaginary parts are nonzero. For each n, define d_n to be the Euclidean distance from the point (n, |z_n|) to the line\n\ny = {slope_num}/{q} \\cdot x + {intercept}.\n\nChoose one complex number at random from \\{z_n\\}_{n=1}^{a}; let p be the probability that its modulus is a positive integer. Suppose the following identity holds:\n\n\\[\n\\Big({c1}\\,{a} - \\sum_{i=1}^{a} i^{d_i}\\Big)^{\\!2}\n+ \\Big({c2_first} + \\sum_{k=2}^{a}({c2_k_coeff}k + {c2_const}) - \\sum_{i=1}^{a} i^{2d_i}\\Big)^{\\!2}\n+ \\Big(\\tfrac{{c3_first_num}}{{c3_first_den}} + \\sum_{j=2}^{a}\\big({c3_j3_coeff}j^3 + {c3_j_coeff}j + \\tfrac{{c3_frac_num}}{{c3_frac_den}}\\big) - \\sum_{i=1}^{a} i^{3d_i}\\Big)^{\\!2} = 0.\n\\]\n\nFind the maximum value of p.\n\nAfter solving the above problem, please output your final answer in the following format:\n### The final answer is: \\boxed{<your answer>}\nExample:\n### The final answer is: \\boxed{\\tfrac{21}{103}}\nThe final answer should be given as precisely as possible (using LaTeX symbols such as \\sqrt, \\frac, \\pi, etc.). If the final answer involves a decimal approximation, it must be accurate to at least four decimal places.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

