    x = a + q
    x += (residue - (x % q)) % q
    while not is_prime(x):
        x += q
    a = x
# Constants chosen to recover the same extremal-moment structure as the seed
c1 = 2
c2_first = 3
c2_k_coeff = 2
c2_const = 2
c3_first_num = 7
c3_first_den = 2
c3_j3_coeff = 3
c3_j_coeff = 3
