    c3_j_coeff = int(assign['c3_j_coeff'])
    c3_frac_num = int(assign['c3_frac_num'])
    c3_frac_den = int(assign['c3_frac_den'])
except Exception:
    # invalid assignment
    return (False, None)
# Validate domain constraints
if not is_prime(a):
    # a must be prime
    return (False, None)
if a <= lower_bound:
    return (False, None)
if q <= 1:
    return (False, None)
if residue <= 0 or residue >= q:
    return (False, None)
if a % q != residue:
    return (False, None)
if gcd(slope_num, q) != 1:
    return (False, None)
if intercept <= 0:
    return (False, None)
# Difficulty guard: ensure at least three multiples of q in 1..a
if a // q < 3:
    return (False, None)
# Moment constants sanity (they are fixed to reproduce the extremal structure)
if not (c1 == 2 and c2_first == 3 and c2_k_coeff == 2 and c2_const == 2 and c3_first_num == 7 and c3_first_den == 2 and c3_j3_coeff == 3 and c3_j_coeff == 3 and c3_frac_num == 1 and c3_frac_den == 2):
    return (False, None)
# Compute the maximum probability p_max.
# As in the seed's extremal argument, the constraints force that a-3 points (all indices except 1 and two exceptional ones) lie on the line.
# With slope slope_num/q and integer intercept, the line yields integer |z_n| exactly when n is a multiple of q.
# We can choose the two exceptional indices to avoid multiples of q (since a is large), so among 2..a we retain all multiples of q.
# Additionally, index 1 can be made to have integer modulus (it is free in the extremal case).
# Therefore, the maximal count of indices with integer modulus is floor(a/q) + 1, giving probability:
numerator = (a // q) + 1
denominator = a
# Reduce the fraction for a clean LaTeX answer
g = gcd(numerator, denominator)
num_red = numerator // g
den_red = denominator // g
